EQUIP, OPERACAO, SLOT, PORT = range(4)
teclado_equip = [["GALC", "GHUA", "GZTE"]]
markup_equip = ReplyKeyboardMarkup(teclado_equip, resize_keyboard=True)

def calc_galc(slot, port):
    pon = (slot * 16 + port - 16)
    slot_icx = math.ceil(pon / 24)
    port_icx = pon - ((slot_icx - 1) * 24)
    return slot_icx, port_icx

def calc_fibra(fibra):
    slot = math.ceil(fibra / 24)
    port = fibra - ((slot - 1) * 24)
    return slot, port

def validar(texto):
    texto = texto.strip()
    if not re.fullmatch(r'\d+', texto):
        return None
    return int(texto)

async def start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    context.user_data.clear()
    await update.message.reply_text("👋 Qual equipamento? GALC, GHUA ou GZTE", reply_markup=markup_equip)
    return EQUIP

async def escolher_equip(update: Update, context: ContextTypes.DEFAULT_TYPE):
    equip = update.message.text.strip().upper()
    if equip not in ["GALC", "GHUA", "GZTE"]:
        await update.message.reply_text("Escolha: GALC, GHUA ou GZTE", reply_markup=markup_equip)
        return EQUIP
    context.user_data['equip'] = equip
    teclado_op = [[f"{equip} -> ICX", "FIBRA -> DGO"], ["DGO -> FIBRA"]]
    markup_op = ReplyKeyboardMarkup(teclado_op, resize_keyboard=True)
    await update.message.reply_text(f"✅ {equip} selecionado.", reply_markup=markup_op)
    return OPERACAO

async def escolher_operacao(update: Update, context: ContextTypes.DEFAULT_TYPE):
    texto = update.message.text.strip().upper()
    equip = context.user_data['equip']
    if texto == f"{equip} -> ICX":
        context.user_data['modo'] = 'equip_icx'
        await update.message.reply_text(f"Digite o SLOT {equip}:")
        return SLOT
    elif texto == "FIBRA -> DGO":
        context.user_data['modo'] = 'fibra_dgo'
        await update.message.reply_text("Digite a FIBRA:")
        return PORT
    elif texto == "DGO -> FIBRA":
        context.user_data['modo'] = 'dgo_fibra'
        await update.message.reply_text("Digite o SLOT DGO:")
        return SLOT
    else:
        teclado_op = [[f"{equip} -> ICX", "FIBRA -> DGO"], ["DGO -> FIBRA"]]
        markup_op = ReplyKeyboardMarkup(teclado_op, resize_keyboard=True)
        await update.message.reply_text("Escolha:", reply_markup=markup_op)
        return OPERACAO

async def receber_slot(update: Update, context: ContextTypes.DEFAULT_TYPE):
    v = validar(update.message.text)
    if v is None:
        await update.message.reply_text("Digite o SLOT (só número):")
        return SLOT
    context.user_data['slot'] = v
    await update.message.reply_text("Digite a PORTA:")
    return PORT

async def receber_port(update: Update, context: ContextTypes.DEFAULT_TYPE):
    v = validar(update.message.text)
    if v is None:
        await update.message.reply_text("Digite a PORTA:")
        return PORT
    modo = context.user_data['modo']
    slot = context.user_data.get('slot', 0)
    port = v
    equip = context.user_data['equip']

    if modo == 'equip_icx':
        if equip == "GHUA":
            res = GHUA_TO_ICX.get((slot, port))
            if not res:
                await update.message.reply_text(f"❌ GHUA {slot}/{port} não existe! GHUA só não tem 9/0-9/15 e 10/0-10/15. Válidos: 1-8,11-19 portas 0-15.", reply_markup=markup_equip)
                await update.message.reply_text("Qual equipamento?", reply_markup=markup_equip)
                return EQUIP
            icx_slot, icx_port = res
            await update.message.reply_text(f"✅ GHUA {slot}/{port}\n➡ ICX: SLOT {icx_slot} PORTA {icx_port}", reply_markup=markup_equip)
        elif equip == "GZTE":
            res = GZTE_TO_ICX.get((slot, port))
            if not res:
                await update.message.reply_text(f"❌ GZTE {slot}/{port} não existe! GZTE só não tem 10/1-10/16 e 11/1-11/16. Válidos: 1-9,12-19 portas 1-16.", reply_markup=markup_equip)
                await update.message.reply_text("Qual equipamento?", reply_markup=markup_equip)
                return EQUIP
            icx_slot, icx_port = res
            await update.message.reply_text(f"✅ GZTE {slot}/{port}\n➡ ICX: SLOT {icx_slot} PORTA {icx_port}", reply_markup=markup_equip)
        else:
            slot_icx, port_icx = calc_galc(slot, port)
            await update.message.reply_text(f"✅ {equip} {slot}/{port}\n➡ ICX: SLOT {slot_icx} PORT {port_icx}", reply_markup=markup_equip)
        await update.message.reply_text("Qual próximo equipamento?", reply_markup=markup_equip)
        return EQUIP
    elif modo == 'dgo_fibra':
        fibra = (slot - 1) * 24 + port
        await update.message.reply_text(f"✅ DGO {slot}/{port}\n➡ FIBRA: {fibra}", reply_markup=markup_equip)
        await update.message.reply_text("Qual equipamento?", reply_markup=markup_equip)
        return EQUIP
    elif modo == 'fibra_dgo':
        fibra = port
        slot_dgo, port_dgo = calc_fibra(fibra)
        await update.message.reply_text(f"🔄 FIBRA {fibra}\n➡ DGO: SLOT {slot_dgo} PORT {port_dgo}", reply_markup=markup_equip)
        await update.message.reply_text("Qual equipamento?", reply_markup=markup_equip)
        return EQUIP

app = Application.builder().token(TOKEN).build()
conv = ConversationHandler(
    entry_points=[CommandHandler("start", start)],
    states={
        EQUIP: [MessageHandler(filters.TEXT & ~filters.COMMAND, escolher_equip)],
        OPERACAO: [MessageHandler(filters.TEXT & ~filters.COMMAND, escolher_operacao)],
        SLOT: [MessageHandler(filters.TEXT & ~filters.COMMAND, receber_slot)],
        PORT: [MessageHandler(filters.TEXT & ~filters.COMMAND, receber_port)],
    },
    fallbacks=[CommandHandler("start", start)],
)
app.add_handler(conv)
app.run_polling()
